        for j in range(W-1):
            if g[i][j]==g[i][j+1]==2 and g[i+1][j]==g[i+1][j+1]==2:
                res.append((i,j,H,W))
    return res

def comps(g):
    H=len(g); W=len(g[0]); seen=[[False]*W for _ in range(H)]; out=[]
    for i in range(H):
        for j in range(W):
            if g[i][j]==2 and not seen[i][j]:
                st=[(i,j)]; seen[i][j]=True; c=[]
                while st:
                    x,y=st.pop(); c.append((x,y))
                    for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
                        a,b=x+dx,y+dy
                        if 0<=a<H and 0<=b<W and g[a][b]==2 and not seen[a][b]:
                            seen[a][b]=True; st.append((a,b))
                out.append(c)
    return out

